448	    if (err != cudaSuccess) return err;
449	    int n_sms = 0;
450	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
451	    if (err != cudaSuccess) return err;
452	
453	    int occ = 0;
454	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
455	        &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK,
456	        /*dynamicSMemBytes=*/0);
457	    if (err != cudaSuccess) return err;
458	    if (occ < 1) return cudaErrorLaunchOutOfResources;
459	
460	    unsigned launch_ctas = (unsigned)n_sms;
461	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
462	    ctx.n_ctas = launch_ctas;
463	    // B%16: the dW K-loop contracts K=T=B·8 in 16-step atoms. It ALSO guarantees
464	    // FULL tiles (T%kTileM==0 for kTileM∈{64,128}), which the projection GEMMs
465	    // REQUIRE — they process a compile-time M-extent of kTileM rows (kAtomsM
466	    // atoms), NOT the runtime `nrows`; a partial final tile would feed garbage
467	    // pad rows to the wgmma while the scalar scan/conv loops process only nsamp.
468	    // (A future relaxation to B%2 would satisfy the K-atom reason but silently
469	    // break partial tiles — keep B%16.)
470	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
471	
472	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
473	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
474	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
