80	static std::vector<torch::Tensor> tc_train_step(
81	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
82	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
83	        double weight_decay, double bc1, double bc2, int64_t step,
84	        int64_t ncta_cap) {
85	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
86	    TORCH_CHECK(params.numel() == kMambaTotalElems, "params must be the flat mamba blob (", kMambaTotalElems, ")");
87	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
88	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
89	    const int B = (int)targets.numel();
90	    TORCH_CHECK(tokens.numel() == (int64_t)B * mb::kSeq, "tokens must be [B,kSeq]");
91	    TORCH_CHECK((B % 16) == 0, "TC path requires B %% 16 == 0 (dW K-loop is 16-step atoms)");
92	    const int64_t total = kMambaTotalElems;
93	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
94	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
95	
96	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
97	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
98	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
99	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
100	
101	    PersistentContext ctx{
102	        sc.g_next.data_ptr<int>(),
103	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
104	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
105	        ::sg::fused::sm90::kMambaNumTensors,
106	        0u};
107	
108	    FusedOptState st;
109	    float* m = state.data_ptr<float>();
110	    st.exp_avg = m;
111	    st.exp_avg_sq = m + total;
112	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
113	    st.eps = (float)eps; st.wd = (float)weight_decay;
114	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
115	
116	    MambaTokenCtx tok;
117	    tok.tokens = tokens.data_ptr<int>();
118	    tok.targets = targets.data_ptr<int>();
119	    tok.B = B;
120	    tok.workspace = sc.workspace.data_ptr<float>();
121	    tok.loss_out = loss_dev.data_ptr<float>();
122	
123	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
124	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel_tc<OptId::AdamW>(
125	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
126	        (float)lr, (int)step, st, stream, nCTA);
127	    TORCH_CHECK(err == cudaSuccess, "TC mamba megakernel launch failed: ", cudaGetErrorString(err));
128	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
129	
130	    return {loss_dev.to(torch::kCPU), grad};
131	}
